import{_ as i,c as a,o as s,j as n,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"git-index-pack | x-cmd man (git man1) | Build pack index file for an existing packed archive","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-index-pack - Build pack index file for an existing packed archive","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-index-pack | x-cmd man (git man1) | Build pack index file for an existing packed archive"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-index-pack - Build pack index file for an existing packed archive"}]]},"headers":[],"params":{"isMan":true,"man":"git-index-pack","category":"git man1","desc":"Build pack index file for an existing packed archive"},"relativePath":"git/man1/git-index-pack.md","filePath":"git/man1/[man].md"}'),p={name:"git/man1/git-index-pack.md"},l={class:"visually-hidden"};function h(t,e,c,d,k,g){return s(),a("div",null,[n("h1",l,r(t.$params.man),1),e[0]||(e[0]=o(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-index-pack - Build pack index file for an existing packed archive</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index-pack</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [-v] [-o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index-file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] [--[no-]rev-index] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pack-file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> index-pack</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --stdin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--fix-thin] [--keep] [-v] [-o </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">index-file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [--[no-]rev-index] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pack-file</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Reads a packed archive (.pack) from the specified file, and builds a pack index file (.idx) for it. Optionally writes a reverse-index (.rev) for the specified pack. The packed archive together with the pack index can then be placed in the objects/pack/ directory of a Git repository.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-v</p><blockquote><p>Be verbose about what is going on, including progress status.</p></blockquote><p>-o &lt;index-file&gt;</p><blockquote><p>Write the generated pack index into the specified file. Without this option the name of pack index file is constructed from the name of packed archive file by replacing .pack with .idx (and the program fails if the name of packed archive does not end with .pack).</p></blockquote><p>--[no-]rev-index</p><blockquote><p>When this flag is provided, generate a reverse index (a <strong>.rev</strong> file) corresponding to the given pack. If <strong>--verify</strong> is given, ensure that the existing reverse index is correct. Takes precedence over <strong>pack.writeReverseIndex</strong>.</p></blockquote><p>--stdin</p><blockquote><p>When this flag is provided, the pack is read from stdin instead and a copy is then written to &lt;pack-file&gt;. If &lt;pack-file&gt; is not specified, the pack is written to objects/pack/ directory of the current Git repository with a default name determined from the pack content. If &lt;pack-file&gt; is not specified consider using --keep to prevent a race condition between this process and <em>git repack</em>.</p></blockquote><p>--fix-thin</p><blockquote><p>Fix a &quot;thin&quot; pack produced by <strong>git pack-objects --thin</strong> (see <strong>git-pack-objects</strong>(1) for details) by adding the excluded objects the deltified objects are based on to the pack. This option only makes sense in conjunction with --stdin.</p></blockquote><p>--keep</p><blockquote><p>Before moving the index into its final destination create an empty .keep file for the associated pack file. This option is usually necessary with --stdin to prevent a simultaneous <em>git repack</em> process from deleting the newly constructed pack and index before refs can be updated to use objects contained in the pack.</p></blockquote><p>--keep=&lt;msg&gt;</p><blockquote><p>Like --keep create a .keep file before moving the index into its final destination, but rather than creating an empty file place <em>&lt;msg&gt;</em> followed by an LF into the .keep file. The <em>&lt;msg&gt;</em> message can later be searched for within all .keep files to locate any which have outlived their usefulness.</p></blockquote><p>--index-version=&lt;version&gt;[,&lt;offset&gt;]</p><blockquote><p>This is intended to be used by the test suite only. It allows to force the version for the generated pack index, and to force 64-bit index entries on objects located above the given offset.</p></blockquote><p>--strict</p><blockquote><p>Die, if the pack contains broken objects or links.</p></blockquote><p>--progress-title</p><blockquote><p>For internal use only.</p><p>Set the title of the progress bar. The title is &quot;Receiving objects&quot; by default and &quot;Indexing objects&quot; when <strong>--stdin</strong> is specified.</p></blockquote><p>--check-self-contained-and-connected</p><blockquote><p>Die if the pack contains broken links. For internal use only.</p></blockquote><p>--fsck-objects</p><blockquote><p>For internal use only.</p><p>Die if the pack contains broken objects. If the pack contains a tree pointing to a .gitmodules blob that does not exist, prints the hash of that blob (for the caller to check) after the hash that goes into the name of the pack/idx file (see &quot;Notes&quot;).</p></blockquote><p>--threads=&lt;n&gt;</p><blockquote><p>Specifies the number of threads to spawn when resolving deltas. This requires that index-pack be compiled with pthreads otherwise this option is ignored with a warning. This is meant to reduce packing time on multiprocessor machines. The required amount of memory for the delta search window is however multiplied by the number of threads. Specifying 0 will cause Git to auto-detect the number of CPU&#39;s and use maximum 3 threads.</p></blockquote><p>--max-input-size=&lt;size&gt;</p><blockquote><p>Die, if the pack is larger than &lt;size&gt;.</p></blockquote><p>--object-format=&lt;hash-algorithm&gt;</p><blockquote><p>Specify the given object format (hash algorithm) for the pack. The valid values are <em>sha1</em> and (if enabled) <em>sha256</em>. The default is the algorithm for the current repository (set by <strong>extensions.objectFormat</strong>), or <em>sha1</em> if no value is set or outside a repository.</p><p>This option cannot be used with --stdin.</p><p>THIS OPTION IS EXPERIMENTAL! SHA-256 support is experimental and still in an early stage. A SHA-256 repository will in general not be able to share work with &quot;regular&quot; SHA-1 repositories. It should be assumed that, e.g., Git internal file formats in relation to SHA-256 repositories may change in backwards-incompatible ways. Only use <strong>--object-format=sha256</strong> for testing purposes.</p></blockquote><p>--promisor[=&lt;message&gt;]</p><blockquote><p>Before committing the pack-index, create a .promisor file for this pack. Particularly helpful when writing a promisor pack with --fix-thin since the name of the pack is not final until the pack has been fully written. If a <strong>&lt;message&gt;</strong> is provided, then that content will be written to the .promisor file for future reference. See <strong>partial clone</strong>[1] for more information.</p></blockquote><h2 id="notes" tabindex="-1">NOTES <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><p>Once the index has been created, the hash that goes into the name of the pack/idx file is printed to stdout. If --stdin was also used then this is prefixed by either &quot;pack\\t&quot;, or &quot;keep\\t&quot; if a new .keep file was successfully created. This is useful to remove a .keep file used as a lock to prevent the race with <em>git repack</em> mentioned above.</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p><h2 id="notes-1" tabindex="-1">NOTES <a class="header-anchor" href="#notes-1" aria-label="Permalink to &quot;NOTES&quot;">​</a></h2><ol><li></li></ol><p>: partial clone</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">file:///usr/share/doc/git/technical/partial-clone.html</span></span></code></pre></div>`,47))])}const m=i(p,[["render",h]]);export{f as __pageData,m as default};
